using System;
using System.Reflection;
using System.Runtime.ExceptionServices;
using Notifications.Legacy;

namespace Notifications;

/// <summary>Sends push notifications.</summary>
public sealed class PushClient
{
    public bool SendPush(Message message)
    {
        var recipientName = message.Recipient.Name;
        var body = message.Body;
        var pushMethod = typeof(PushApiV1).GetMethod(
            "Push",
            BindingFlags.Public | BindingFlags.Static,
            binder: null,
            types: new[] { typeof(string), typeof(string) },
            modifiers: null)
            ?? throw new MissingMethodException(typeof(PushApiV1).FullName, "Push");

        try
        {
            return (bool)pushMethod.Invoke(null, new object[] { recipientName, body });
        }
        catch (TargetInvocationException exception) when (exception.InnerException != null)
        {
            ExceptionDispatchInfo.Capture(exception.InnerException).Throw();
            throw;
        }
    }
}
